1	package netproxy
2	
3	import (
4		"bytes"
5		"context"
6		"crypto/tls"
7		"crypto/x509"
8		"errors"
9		"fmt"
10		"io"
11		"net/http"
12		"net/http/httptest"
13		"net/url"
14		"os"
15		"os/exec"
16		"reflect"
17		"strings"
18		"testing"
19		"time"
20	
21		"github.com/anthnel/devdesk/internal/testutil/connectproxy"
22	)
23	
24	const (
25		// helperEnv makes the test binary run TestFromEnvironmentHelper for real.
26		helperEnv = "NETPROXY_TEST_HELPER"
27		// helperTarget is the URL the helper asks FromEnvironment about.
28		helperTarget = "NETPROXY_TEST_TARGET"
29		// resultPrefix marks the helper's answer among the test binary's output.
30		resultPrefix = "RESULT "
31	)
32	
33	func mustURL(t testing.TB, raw string) *url.URL {
34		t.Helper()
35		u, err := url.Parse(raw)
36		if err != nil {
37			t.Fatalf("parsing %q: %v", raw, err)
38		}
39		return u
40	}
41	
42	// fixed is a Selector that always picks proxy.
43	func fixed(proxy *url.URL) Selector {
44		return func(*url.URL) (*url.URL, error) { return proxy, nil }
45	}
46	
47	// direct is a Selector that never picks a proxy.
48	func direct(*url.URL) (*url.URL, error) { return nil, nil }
49	
50	func sameURL(a, b *url.URL) bool {
51		if a == nil || b == nil {
52			return a == b
53		}
54		return a.String() == b.String()
55	}
56	
57	func TestSelectorForRequest(t *testing.T) {
58		proxy := mustURL(t, "http://proxy.corp:3128")
59		boom := errors.New("invalid proxy setting")
60		tests := []struct {
61			name    string
62			sel     Selector
63			want    *url.URL
64			wantErr error
65		}{
66			{"a proxy", fixed(proxy), proxy, nil},
67			{"direct", direct, nil, nil},
68			{"an error", func(*url.URL) (*url.URL, error) { return nil, boom }, nil, boom},
69		}
70		for _, tt := range tests {
71			t.Run(tt.name, func(t *testing.T) {
72				got, err := tt.sel.ForRequest(&http.Request{URL: mustURL(t, "https://example.com/")})
73				if !errors.Is(err, tt.wantErr) {
74					t.Fatalf("error = %v, want %v", err, tt.wantErr)
75				}
76				if !sameURL(got, tt.want) {
77					t.Fatalf("proxy = %v, want %v", got, tt.want)
78				}
79			})
80		}
81	}
82	
83	func TestSelectorForRequestPassesTheRequestURL(t *testing.T) {
84		var seen *url.URL
85		sel := Selector(func(u *url.URL) (*url.URL, error) { seen = u; return nil, nil })
86		req := &http.Request{URL: mustURL(t, "https://a.corp.test:8443/path?q=1")}
87		if _, err := sel.ForRequest(req); err != nil {
88			t.Fatal(err)
89		}
90		if seen != req.URL {
91			t.Fatalf("selector saw %v, want the request's own URL %v", seen, req.URL)
92		}
93	}
94	
95	func TestNewTransportProxyFollowsTheSelector(t *testing.T) {
96		proxy := mustURL(t, "http://proxy.corp:3128")
97		tests := []struct {
98			name string
99			sel  Selector
100			want *url.URL
101		}{
102			{"a proxy", fixed(proxy), proxy},
103			{"direct", direct, nil},
104		}
105		for _, tt := range tests {
106			t.Run(tt.name, func(t *testing.T) {
107				tr := NewTransport(tt.sel)
108				if tr.Proxy == nil {
109					t.Fatal("Transport.Proxy is nil")
110				}
111				got, err := tr.Proxy(&http.Request{URL: mustURL(t, "https://example.com/")})
112				if err != nil {
113					t.Fatalf("Proxy: %v", err)
114				}
115				if !sameURL(got, tt.want) {
116					t.Fatalf("Proxy = %v, want %v", got, tt.want)
117				}
118			})
119		}
120	}
121	
122	func TestNewTransportProxyReportsTheSelectorError(t *testing.T) {
123		boom := errors.New("invalid proxy setting")
124		tr := NewTransport(func(*url.URL) (*url.URL, error) { return nil, boom })
125		if tr.Proxy == nil {
126			t.Fatal("Transport.Proxy is nil")
127		}
128		if _, err := tr.Proxy(&http.Request{URL: mustURL(t, "https://example.com/")}); !errors.Is(err, boom) {
129			t.Fatalf("Proxy error = %v, want %v", err, boom)
130		}
131	}
132	
133	// TestNewTransportKeepsTheDefaultTransportSettings checks every exported field
134	// but Proxy (and the two the standard library fills lazily) against
135	// http.DefaultTransport, so the HTTPS monitor's timeouts and limits carry over.
136	func TestNewTransportKeepsTheDefaultTransportSettings(t *testing.T) {
137		skip := map[string]bool{"Proxy": true, "TLSClientConfig": true, "TLSNextProto": true}
138		def := reflect.ValueOf(http.DefaultTransport.(*http.Transport).Clone()).Elem()
139		got := reflect.ValueOf(NewTransport(direct)).Elem()
140		typ := got.Type()
141		for i := 0; i < typ.NumField(); i++ {
142			f := typ.Field(i)
143			if !f.IsExported() || skip[f.Name] {
144				continue
145			}
146			g, d := got.Field(i), def.Field(i)
147			if g.Kind() == reflect.Func {
148				if g.IsNil() != d.IsNil() {
149					t.Errorf("%s: nil = %v, DefaultTransport nil = %v", f.Name, g.IsNil(), d.IsNil())
150				}
151				continue
152			}
153			if !reflect.DeepEqual(g.Interface(), d.Interface()) {
154				t.Errorf("%s = %v, DefaultTransport has %v", f.Name, g.Interface(), d.Interface())
155			}
156		}
157		if got.FieldByName("DialContext").IsNil() {
158			t.Error("DialContext is nil: connections would not use the default dialer")
159		}
160	}
161	
162	func TestNewTransportIsACopyNotDefaultTransport(t *testing.T) {
163		a, b := NewTransport(direct), NewTransport(direct)
164		if a == http.DefaultTransport || a == b {
165			t.Fatal("NewTransport returned a shared transport")
166		}
167		before := http.DefaultTransport.(*http.Transport).MaxIdleConns
168		a.MaxIdleConns = before + 7
169		if http.DefaultTransport.(*http.Transport).MaxIdleConns != before {
170			t.Fatal("editing the new transport changed http.DefaultTransport")
171		}
172		if b.MaxIdleConns != before {
173			t.Fatal("editing one transport changed another")
174		}
175		if p := http.DefaultTransport.(*http.Transport).Proxy; p == nil {
176			t.Fatal("http.DefaultTransport lost its Proxy")
177		}
178	}
179	
180	// httpsGet fetches rawURL through tr, trusting only srv's certificate.
181	func httpsGet(t *testing.T, tr *http.Transport, srv *httptest.Server, rawURL string) (*http.Response, string) {
182		t.Helper()
183		pool := x509.NewCertPool()
184		pool.AddCert(srv.Certificate())
185		tr.TLSClientConfig = &tls.Config{RootCAs: pool}
186		t.Cleanup(tr.CloseIdleConnections)
187		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
188		defer cancel()
189		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
190		if err != nil {
191			t.Fatal(err)
192		}
193		resp, err := (&http.Client{Transport: tr}).Do(req)
194		if err != nil {
195			t.Fatalf("GET %s: %v", rawURL, err)
196		}
197		defer func() { _ = resp.Body.Close() }()
198		body, _ := io.ReadAll(resp.Body)
199		return resp, string(body)
200	}
201	
202	func newTLSServer(t *testing.T) *httptest.Server {
203		t.Helper()
204		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
205			_, _ = io.WriteString(w, "reached")
206		}))
207		t.Cleanup(srv.Close)
208		return srv
209	}
210	
211	func TestNewTransportTunnelsThroughTheSelectedProxy(t *testing.T) {
212		srv := newTLSServer(t)
213		// example.com is a name in the httptest certificate; the proxy redirects it
214		// to the real listener.
215		proxy := connectproxy.Start(t, connectproxy.Options{
216			Route: func(string) string { return srv.Listener.Addr().String() },
217		})
218		resp, body := httpsGet(t, NewTransport(fixed(proxy.URL())), srv, "https://example.com/")
219		if resp.StatusCode != http.StatusOK || body != "reached" {
220			t.Fatalf("answer = %d %q, want 200 %q", resp.StatusCode, body, "reached")
221		}
222		want := []connectproxy.Request{{Target: "example.com:443"}}
223		if got := proxy.Requests(); !reflect.DeepEqual(got, want) {
224			t.Fatalf("proxy received %+v, want exactly %+v", got, want)
225		}
226	}
227	
228	func TestNewTransportGoesDirectWhenTheSelectorSaysSo(t *testing.T) {
229		srv := newTLSServer(t)
230		proxy := connectproxy.Start(t, connectproxy.Options{})
231		resp, body := httpsGet(t, NewTransport(direct), srv, srv.URL)
232		if resp.StatusCode != http.StatusOK || body != "reached" {
233			t.Fatalf("answer = %d %q, want 200 %q", resp.StatusCode, body, "reached")
234		}
235		if got := proxy.Requests(); len(got) != 0 {
236			t.Fatalf("a direct connection reached the proxy: %+v", got)
237		}
238	}
239	
240	func TestNewTransportSurfacesAProxyRefusal(t *testing.T) {
241		srv := newTLSServer(t)
242		proxy := connectproxy.Start(t, connectproxy.Options{Refuse: http.StatusForbidden})
243		pool := x509.NewCertPool()
244		pool.AddCert(srv.Certificate())
245		tr := NewTransport(fixed(proxy.URL()))
246		tr.TLSClientConfig = &tls.Config{RootCAs: pool}
247		t.Cleanup(tr.CloseIdleConnections)
248		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
249		defer cancel()
250		req, _ := http.NewRequestWithContext(ctx, http.MethodGet, "https://example.com/", nil)
251		resp, err := (&http.Client{Transport: tr}).Do(req)
252		if err == nil {
253			_ = resp.Body.Close()
254			t.Fatal("GET through a refusing proxy succeeded")
255		}
256		if got := proxy.Requests(); len(got) != 1 {
257			t.Fatalf("proxy received %d CONNECTs, want 1", len(got))
258		}
259	}
260	
261	// TestFromEnvironmentIsHTTPProxyFromEnvironment holds in any environment: both
262	// calls read the same per-process cache.
263	func TestFromEnvironmentIsHTTPProxyFromEnvironment(t *testing.T) {
264		tests := []string{
265			"https://example.com:443",
266			"https://a.corp.test:8443",
267			"https://localhost:8443",
268			"https://127.0.0.1:8443",
269			"https://10.1.2.3:443",
270			"http://example.com:80",
271		}
272		for _, raw := range tests {
273			t.Run(raw, func(t *testing.T) {
274				u := mustURL(t, raw)
275				want, wantErr := http.ProxyFromEnvironment(&http.Request{URL: u})
276				got, err := FromEnvironment(u)
277				if (err == nil) != (wantErr == nil) {
278					t.Fatalf("error = %v, want %v", err, wantErr)
279				}
280				if !sameURL(got, want) {
281					t.Fatalf("proxy = %v, want %v", got, want)
282				}
283			})
284		}
285	}
286	
287	// TestFromEnvironmentHelper is the child half of TestFromEnvironmentFollowsTheEnvironment.
288	// It does nothing in a normal run. http.ProxyFromEnvironment reads the proxy
289	// variables once per process, so t.Setenv cannot steer it: the parent runs the
290	// test binary again with the variables it wants.
291	func TestFromEnvironmentHelper(t *testing.T) {
292		if os.Getenv(helperEnv) != "1" {
293			t.Skip("child of TestFromEnvironmentFollowsTheEnvironment")
294		}
295		proxy, err := FromEnvironment(mustURL(t, os.Getenv(helperTarget)))
296		switch {
297		case err != nil:
298			fmt.Println(resultPrefix + "error: " + err.Error())
299		case proxy == nil:
300			fmt.Println(resultPrefix + "direct")
301		default:
302			fmt.Println(resultPrefix + proxy.String())
303		}
304	}
305	
306	var proxyVars = []string{
307		"HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy",
308		"NO_PROXY", "no_proxy", "REQUEST_METHOD", helperEnv, helperTarget,
309	}
310	
311	// runHelper runs the child with exactly the given proxy variables and returns
312	// what it answered.
313	func runHelper(t *testing.T, target string, vars map[string]string) string {
314		t.Helper()
315		var env []string
316		for _, kv := range os.Environ() {
317			name, _, _ := strings.Cut(kv, "=")
318			drop := false
319			for _, v := range proxyVars {
320				if strings.EqualFold(name, v) {
321					drop = true
322				}
323			}
324			if !drop {
325				env = append(env, kv)
326			}
327		}
328		env = append(env, helperEnv+"=1", helperTarget+"="+target)
329		for k, v := range vars {
330			env = append(env, k+"="+v)
331		}
332		cmd := exec.Command(os.Args[0], "-test.run=^TestFromEnvironmentHelper$", "-test.count=1")
333		cmd.Env = env
334		var out bytes.Buffer
335		cmd.Stdout, cmd.Stderr = &out, &out
336		if err := cmd.Run(); err != nil {
337			t.Fatalf("running the helper: %v\n%s", err, out.String())
338		}
339		for _, line := range strings.Split(out.String(), "\n") {
340			if rest, ok := strings.CutPrefix(strings.TrimSpace(line), resultPrefix); ok {
341				return rest
342			}
343		}
344		t.Fatalf("the helper printed no %q line:\n%s", resultPrefix, out.String())
345		return ""
346	}
347	
348	func TestFromEnvironmentFollowsTheEnvironment(t *testing.T) {
349		const proxy = "http://proxy.corp:3128"
350		tests := []struct {
351			name   string
352			target string
353			vars   map[string]string
354			want   string
355		}{
356			{"no variable", "https://example.com:443", nil, "direct"},
357			{"HTTPS_PROXY", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy}, proxy},
358			{"https_proxy in lower case", "https://a.corp.test:443", map[string]string{"https_proxy": proxy}, proxy},
359			{"HTTP_PROXY does not carry https", "https://a.corp.test:443", map[string]string{"HTTP_PROXY": proxy}, "direct"},
360			{"userinfo is kept for the dialer", "https://a.corp.test:443",
361				map[string]string{"HTTPS_PROXY": "REDACTED"}, "REDACTED"},
362			{"https proxy scheme", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": "https://proxy.corp:3129"}, "https://proxy.corp:3129"},
363			{"NO_PROXY exact name", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "a.corp.test"}, "direct"},
364			{"no_proxy in lower case", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "no_proxy": "a.corp.test"}, "direct"},
365			{"NO_PROXY domain covers a sub-domain", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "corp.test"}, "direct"},
366			{"NO_PROXY leading dot covers a sub-domain", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": ".corp.test"}, "direct"},
367			{"NO_PROXY leading dot leaves the domain itself", "https://corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": ".corp.test"}, proxy},
368			{"NO_PROXY other name", "https://b.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "a.corp.test"}, proxy},
369			{"NO_PROXY CIDR", "https://10.1.2.3:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "10.0.0.0/8"}, "direct"},
370			{"NO_PROXY CIDR leaves other addresses", "https://192.168.1.1:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "10.0.0.0/8"}, proxy},
371			{"NO_PROXY star", "https://a.corp.test:443", map[string]string{"HTTPS_PROXY": proxy, "NO_PROXY": "*"}, "direct"},
372			{"localhost is never proxied", "https://localhost:8443", map[string]string{"HTTPS_PROXY": proxy}, "direct"},
373			{"loopback address is never proxied", "https://127.0.0.1:8443", map[string]string{"HTTPS_PROXY": proxy}, "direct"},
374			{"*.localhost is proxied", "https://foo.localhost:8443", map[string]string{"HTTPS_PROXY": proxy}, proxy},
375		}
376		for _, tt := range tests {
377			t.Run(tt.name, func(t *testing.T) {
378				if got := runHelper(t, tt.target, tt.vars); got != tt.want {
379					t.Fatalf("FromEnvironment(%s) with %v = %q, want %q", tt.target, tt.vars, got, tt.want)
380				}
381			})
382		}
383	}
