385	// TestNilSelectorIsFromEnvironment pins the documented default: a nil Selector
386	// decides like FromEnvironment, in ForRequest and in NewTransport.
387	func TestNilSelectorIsFromEnvironment(t *testing.T) {
388		u := mustURL(t, "https://a.corp.test:443")
389		want, wantErr := FromEnvironment(u)
390		req := &http.Request{URL: u}
391		var sel Selector
392		check := func(name string, got *url.URL, err error) {
393			t.Helper()
394			if (err == nil) != (wantErr == nil) || !sameURL(got, want) {
395				t.Errorf("%s = %v, %v; want %v, %v", name, got, err, want, wantErr)
396			}
397		}
398		got, err := sel.ForRequest(req)
399		check("ForRequest", got, err)
400		tr := NewTransport(nil)
401		if tr.Proxy == nil {
402			t.Fatal("Transport.Proxy is nil")
403		}
404		got, err = tr.Proxy(req)
405		check("NewTransport(nil).Proxy", got, err)
406	}
