117	func TestProxyRoutesToTheRealServer(t *testing.T) {
118		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
119			_, _ = io.WriteString(w, "reached")
120		}))
121		defer srv.Close()
122		pool := x509.NewCertPool()
123		pool.AddCert(srv.Certificate())
124	
125		tests := []struct {
126			name string
127			opts func(realAddr string) Options
128		}{
129			{"http proxy", func(real string) Options {
130				return Options{Route: func(string) string { return real }}
131			}},
132			{"https proxy", func(real string) Options {
133				return Options{TLS: true, Route: func(string) string { return real }}
134			}},
135		}
136		for _, tt := range tests {
137			t.Run(tt.name, func(t *testing.T) {
138				var mu sync.Mutex
139				var routed []string
140				opts := tt.opts(srv.Listener.Addr().String())
141				inner := opts.Route
142				opts.Route = func(target string) string {
143					mu.Lock()
144					defer mu.Unlock()
145					routed = append(routed, target)
146					return inner(target)
147				}
148				p := Start(t, opts)
149	
150				// example.com is in the httptest certificate; the proxy sends it to
151				// the real listener.
152				conn := dialProxy(t, p)
153				resp, br := connect(t, conn, "example.com:443")
154				if resp.StatusCode != http.StatusOK {
155					t.Fatalf("CONNECT answered %d, want 200", resp.StatusCode)
156				}
157				_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
158				tlsConn := tls.Client(&bufConn{Conn: conn, r: br}, &tls.Config{ServerName: "example.com", RootCAs: pool})
159				if err := tlsConn.Handshake(); err != nil {
160					t.Fatalf("handshake through the tunnel: %v", err)
161				}
162				if _, err := io.WriteString(tlsConn, "GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n"); err != nil {
163					t.Fatalf("writing through the tunnel: %v", err)
164				}
165				body, _ := io.ReadAll(tlsConn)
166				if !strings.Contains(string(body), "reached") {
167					t.Fatalf("answer through the tunnel = %q, want it to contain %q", body, "reached")
168				}
169				mu.Lock()
170				defer mu.Unlock()
171				if len(routed) != 1 || routed[0] != "example.com:443" {
172					t.Fatalf("Route saw %v, want [example.com:443]", routed)
173				}
174			})
175		}
176	}
